begin;
delete from financeiro.lancamentos where user_id='7544d66c-ed9b-496d-8bfa-9819590a4b5a';
delete from financeiro.categorias where user_id='7544d66c-ed9b-496d-8bfa-9819590a4b5a';
delete from financeiro.formas_pagamento where user_id='7544d66c-ed9b-496d-8bfa-9819590a4b5a';
commit;

select count(*) as total,
  count(*) filter (where projetado) as parcelas_futuras,
  count(*) filter (where recorrente) as recorrentes,
  count(*) filter (where parcela_num is not null) as com_numero_parcela
from financeiro.lancamentos where user_id='7544d66c-ed9b-496d-8bfa-9819590a4b5a';
